<script setup>
import { computed, ref, watch } from 'vue';
import { Icon } from '@iconify/vue';
const props = defineProps({ session: Object, busy: Boolean, pending: Boolean, canAnswer: Boolean, answer: String });
const emit = defineEmits(['update:answer', 'confirm', 'answer', 'new-task']);
const selected = ref({});
const questions = computed(() => (props.session?.questions || []).filter(Boolean));
const stages = computed(() => props.session?.progress?.stages || []);
const messages = computed(() => props.session?.messages || []);
const answered = computed(() => questions.value.filter((q) => selected.value[q.id || q.text]).length);
const allAnswered = computed(() => questions.value.length > 0 && answered.value === questions.value.length);
watch(() => props.session?.id, () => { selected.value = {}; }, { immediate: true });
function choose(question, option) { selected.value[question.id || question.text] = option; }
function submitAnswers() { const text = questions.value.map((q) => `${q.text || q.question}\n我的选择：${selected.value[q.id || q.text]}`).join('\n\n'); emit('update:answer', text); emit('answer'); selected.value = {}; }
</script>
<template>
  <section v-if="session" class="collaboration-ui" aria-live="polite">
    <div class="conversation">
      <div v-for="(item,index) in messages" :key="index" class="message" :class="`is-${item.role || 'assistant'}`"><span>{{ item.role === 'user' ? '你' : 'AI' }}</span><p>{{ item.content || item.message }}</p></div>
      <div v-if="pending" class="thinking"><i></i><i></i><i></i><span>{{ session.message || '等待模型响应' }}</span></div>
      <div v-if="session.error" class="error" role="alert"><Icon icon="solar:danger-triangle-linear" width="16"/>{{ session.error }}</div>
      <section v-if="stages.length" class="stages"><div v-for="stage in stages" :key="stage.id" :class="`is-${stage.status}`"><Icon :icon="stage.status==='completed'?'solar:check-circle-bold':stage.status==='error'?'solar:danger-circle-bold':stage.status==='running'?'solar:refresh-circle-linear':'solar:circle-linear'" width="15"/><span><b>{{ stage.label }}</b><small v-if="stage.message">{{ stage.message }}</small></span></div></section>
      <section v-if="questions.length && !pending" class="questions"><article v-for="question in questions" :key="question.id || question.text"><p>{{ question.text || question.question }}</p><div v-if="question.options?.length" class="options"><button v-for="option in question.options" :key="option" type="button" :class="{selected:selected[question.id || question.text]===option}" @click="choose(question,option)">{{ option }}</button></div></article><button v-if="allAnswered" type="button" class="submit-answers" @click="submitAnswers"><Icon icon="solar:check-circle-linear" width="15"/>提交全部确认（{{ answered }}/{{ questions.length }}）</button><small v-else>请完成全部选择（{{ answered }}/{{ questions.length }}）</small></section>
      <section v-if="session.confirmation && !pending" class="confirmation"><h4><Icon icon="solar:document-text-linear" width="15"/>生成方案确认</h4><p>{{ session.confirmation.confirmed_prompt_zh }}</p><details><summary>查看执行提示词</summary><pre>{{ session.confirmation.execution_prompt_en }}</pre></details></section>
    </div>
    <div class="input-wrap"><textarea :value="answer" :disabled="!canAnswer" rows="1" placeholder="补充人物、素材关系或镜头要求…" @input="emit('update:answer',$event.target.value)" @keydown.enter.exact.prevent="canAnswer&&emit('answer')"></textarea><button type="button" :disabled="!canAnswer || !answer?.trim()" aria-label="发送消息" @click="emit('answer')"><Icon icon="solar:arrow-up-linear" width="17"/></button></div>
    <footer v-if="session.confirmation && !pending"><span><Icon icon="solar:check-circle-bold" width="15"/>已完成生成前检查</span><button type="button" :disabled="busy" @click="emit('confirm')"><Icon icon="solar:play-circle-linear" width="16"/>按此方案生成</button></footer>
  </section>
</template>
<style scoped>
.collaboration-ui{box-sizing:border-box;flex:1;height:100%;min-height:0;overflow:hidden;display:flex;flex-direction:column;min-height:0;color:#dfe6de;font-size:12px}.conversation{flex:1;min-height:0;max-height:none;overflow:auto;padding:14px 14px 2px;scrollbar-width:none}.conversation::-webkit-scrollbar{display:none}.message{display:flex;flex-direction:column;align-items:flex-start;gap:3px;margin:0 0 12px}.message.is-user{align-items:flex-end}.message>span{color:#8f988d;font-size:10px}.message p{max-width:88%;margin:0;padding:8px 10px;border-radius:10px;background:#202426;color:#d7ded5;line-height:1.55;white-space:pre-wrap}.message.is-user p{background:#b7f34a;color:#18200f}.thinking{display:flex;align-items:center;gap:5px;margin:3px 0 12px;color:#969f95;font-size:10px}.thinking i{width:5px;height:5px;border-radius:50%;background:var(--lime);animation:blink 1.1s infinite}.thinking i:nth-child(2){animation-delay:.16s}.thinking i:nth-child(3){animation-delay:.32s}.error{display:flex;gap:6px;margin:0 0 12px;color:#f0a09a;line-height:1.5}.stages{display:grid;gap:2px;margin:0 0 12px;padding:8px 10px;border:1px solid #ffffff12;border-radius:8px;background:#121415}.stages>div{display:grid;grid-template-columns:18px minmax(0,1fr);gap:7px;min-height:29px;padding:5px 2px;color:#687168}.stages span{display:grid;gap:2px}.stages b{font-size:11px;font-weight:500}.stages small{color:#788078;font-size:9px}.stages .is-running{color:var(--lime)}.stages .is-completed{color:#a9cf70}.questions,.confirmation{margin:0 0 12px;border-top:1px solid #ffffff12;padding-top:9px}.questions article{padding:5px 0 4px}.questions p{margin:0 0 8px;line-height:1.5}.options{display:flex;flex-wrap:wrap;gap:6px}.options button,.submit-answers{min-height:31px;padding:0 11px;border:1px solid #ffffff1e;border-radius:8px;background:#292c2e;color:#c6ccc4;font-size:10px;cursor:pointer}.options button:hover{border-color:#b7f34a66;color:var(--lime)}.options button.selected{border-color:#b7f34a88;background:#b7f34a18;color:var(--lime);box-shadow:inset 0 0 0 1px #b7f34a22}.questions>small{display:block;margin-top:8px;color:#777e76;font-size:10px}.submit-answers{display:inline-flex;align-items:center;gap:6px;margin-top:10px;border:1px solid #8dcc31;background:#b7f34a;color:#18200f;font-weight:600;cursor:pointer;box-shadow:0 2px 8px #b7f34a22}.confirmation h4{display:flex;align-items:center;gap:6px;margin:0 0 7px;color:var(--lime);font-size:11px;font-weight:500}.confirmation p{margin:0;padding:9px;border:1px solid #b7f34a30;border-radius:8px;background:#b7f34a08;line-height:1.6;white-space:pre-wrap}.confirmation details{margin-top:7px}.confirmation summary{color:#929a91;font-size:10px;cursor:pointer}.confirmation pre{max-height:130px;margin:7px 0 0;padding:8px;overflow:auto;background:#111315;color:#bfc5bd;font:10px/1.6 ui-monospace,Consolas,monospace;white-space:pre-wrap}.input-wrap{display:flex;align-items:flex-end;gap:8px;margin:0 12px 12px;padding:8px 8px 8px 12px;border:1px solid #ffffff1f;border-radius:10px;background:#111315}.input-wrap:focus-within{border-color:#b7f34a66}.input-wrap textarea{flex:1;min-width:0;min-height:30px;max-height:90px;padding:5px 0;resize:none;outline:0;border:0;background:transparent;color:#e4e7e1;font-size:12px;line-height:20px}.input-wrap textarea::placeholder{color:#626760}.input-wrap button{display:grid;place-items:center;flex:none;width:31px;height:31px;border:0;border-radius:50%;background:var(--lime);color:#171914;cursor:pointer}.input-wrap button:disabled{opacity:.28;cursor:default}footer{display:flex;align-items:center;justify-content:space-between;gap:8px;min-height:48px;padding:8px 12px;border-top:1px solid var(--line);background:#191b1c}footer span{display:flex;align-items:center;gap:5px;color:#969c94;font-size:10px}footer span svg{color:var(--lime)}footer button{display:flex;align-items:center;gap:6px;height:32px;padding:0 11px;border:1px solid #8dcc31;border-radius:8px;background:#b7f34a;color:#18200f;font-size:10px;font-weight:600;cursor:pointer}footer button:hover{background:#c5fa69}.collaboration-ui button:disabled{opacity:.5;cursor:default}@keyframes blink{0%,60%,100%{opacity:.25;transform:translateY(0)}30%{opacity:1;transform:translateY(-2px)}}
</style>
